# backend/shared/python_utils/image_safety/messages.py
#
# Tiered user-facing messages for image safety rejections.
#
# Architecture: docs/architecture/image-safety-pipeline.md §9
#
# Rules (hard):
# - Never reveal classifier details to the user
# - Never leak which signal fired
# - Messages are versioned here, not generated by the LLM
# - The LLM gets the prepared message + a do_not_retry flag

from typing import Any, Dict

# Tier-level messages. Keep these intentionally vague for CSAM, NCII, and
# adversarial bypass attempts — we do not want to give attackers feedback on
# what specifically tripped the classifier.
_VAGUE_MESSAGE = "This image couldn't be generated."
_PUBLIC_FIGURE_MESSAGE = (
    "I can't generate or edit images of public figures at the moment."
)
_MINOR_SAFE_MESSAGE = (
    "I can only apply background, lighting, or colorization edits to images "
    "containing minors."
)
_MODERATE_MESSAGE = (
    "This specific image or prompt couldn't be used. You can try a different "
    "subject or phrasing."
)

# Category → (tier, severity, message)
CATEGORY_MAP: Dict[str, Dict[str, str]] = {
    "S1_csam": {
        "tier": "critical",
        "severity": "critical",
        "message": _VAGUE_MESSAGE,
    },
    "S2_ncii": {
        "tier": "critical",
        "severity": "critical",
        "message": _VAGUE_MESSAGE,
    },
    "S3_sexual_other": {
        "tier": "severe",
        "severity": "severe",
        "message": _VAGUE_MESSAGE,
    },
    "S4_violent_recontextualization": {
        "tier": "severe",
        "severity": "severe",
        "message": _MODERATE_MESSAGE,
    },
    "S5_minor_restricted_edit": {
        "tier": "severe",
        "severity": "severe",
        "message": _MINOR_SAFE_MESSAGE,
    },
    "S6_public_figure_blocked": {
        "tier": "moderate",
        "severity": "moderate",
        "message": _PUBLIC_FIGURE_MESSAGE,
    },
    "S7_identity_replacement": {
        "tier": "severe",
        "severity": "severe",
        "message": _VAGUE_MESSAGE,
    },
    "S8_id_document": {
        "tier": "severe",
        "severity": "severe",
        "message": _VAGUE_MESSAGE,
    },
    "S9_hate_symbol": {
        "tier": "critical",
        "severity": "critical",
        "message": _VAGUE_MESSAGE,
    },
    "S10_self_harm": {
        "tier": "critical",
        "severity": "critical",
        "message": _VAGUE_MESSAGE,
    },
    "S11_weapon_instruction": {
        "tier": "severe",
        "severity": "severe",
        "message": _VAGUE_MESSAGE,
    },
    "S12_adversarial_bypass": {
        "tier": "adversarial",
        "severity": "adversarial",
        "message": _VAGUE_MESSAGE,
    },
    # Reasoner / infra failure categories — severe fail-closed
    "safeguard_error": {
        "tier": "severe",
        "severity": "severe",
        "message": _MODERATE_MESSAGE,
    },
    "safeguard_not_configured": {
        "tier": "severe",
        "severity": "severe",
        "message": _MODERATE_MESSAGE,
    },
    "safeguard_parse_error": {
        "tier": "severe",
        "severity": "severe",
        "message": _MODERATE_MESSAGE,
    },
    "sightengine_not_configured": {
        "tier": "severe",
        "severity": "severe",
        "message": _MODERATE_MESSAGE,
    },
    "unknown": {
        "tier": "moderate",
        "severity": "moderate",
        "message": _MODERATE_MESSAGE,
    },
}


def category_info(category: str) -> Dict[str, str]:
    """Return tier/severity/message for a category (with unknown-safe fallback)."""
    return CATEGORY_MAP.get(category, CATEGORY_MAP["unknown"])


def user_facing_message(category: str) -> str:
    """Return the user-visible message for a rejection category."""
    return category_info(category)["message"]


def build_rejection_payload(category: str) -> Dict[str, Any]:
    """
    Build the structured tool response returned to the LLM on rejection, in
    English. The image task replaces it with the user's language
    (explanations.localized_rejection_payload) before it is shown or cached.

    The LLM explains the reason and offers the allowed alternative, and MUST NOT
    retry in the same response — `do_not_retry: true` is enforced by the
    pipeline auto-reject cache keyed on assistant_response_id.
    """
    from .explanations import localized_rejection_payload

    return localized_rejection_payload(category, "en")

TECHNICAL_CATEGORIES = frozenset({
    "safeguard_error",
    "safeguard_not_configured",
    "safeguard_parse_error",
    "sightengine_not_configured",
})


def is_technical_category(category: str) -> bool:
    """True when the category marks an unavailable or failing safety check."""
    return category in TECHNICAL_CATEGORIES


def build_unavailable_payload(message: str) -> Dict[str, Any]:
    """Tool response for a request refused because a safety check was unavailable."""
    return {
        "error": "safety_check_unavailable",
        "category": "safety_check_unavailable",
        "user_facing_message": message,
        "instructions_to_llm": (
            "The safety check is temporarily unavailable; this is not a policy "
            "violation. Do not call images-generate again in this response. "
            "Tell the user, in their language, that the image could not be "
            "checked right now and that they can try again in a moment."
        ),
        "do_not_retry": True,
    }
